def starts_one_ends(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    # For n-digit numbers, there are 10^(n-1) numbers that start with 1
    # and 10^(n-1) numbers that end with 1. However, we double count
    # the numbers that both start and end with 1, which is 10^(n-2).
    return 2 * (10 ** (n - 1)) - (10 ** (n - 2))
