        num = operand[i + 1]
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '//':
            if num == 0:
                raise ZeroDivisionError("Division by zero")
            result //= num
        elif op == '**':
            result **= num
        else:
            raise ValueError("Invalid operator")
